-- An Empire Divided's creature tables run over two facing pages: the names
-- and HAM on the left, to-hit, XP, behaviour and special attacks on the
-- right. On the three pages where a planet's table starts partway down
-- (pp. 424, 428, 468), the transcription (039-048) paired each row below
-- the heading with the facing row above or below it: a level 95 ancient
-- bull rancor had 564 XP. The rows were read again from the page images,
-- paired by position (the book's XP by level confirms it), and corrected
-- in mmoserverdb/reference/prima_ed/creatures.csv; this updates the 23
-- creatures' templates (Dathomir 15, Endor 6, Tatooine 2) and their lairs'
-- XP.

-- Dathomir: ancient bull rancor (pp. 424-425)
UPDATE swganh.non_persistent_npc_attributes SET value = '55' WHERE npc_id = (SELECT id FROM swganh.non_persistent_npcs WHERE id BETWEEN 5001 AND 5999 AND stf_variable_id = 'ancient_bull_rancor' AND level = 95) AND attribute_id = (SELECT id FROM swganh.attributes WHERE name = 'creature_tohit');
