UPDATE swganh.lair_attributes la JOIN swganh.lairs l ON l.id = la.lair_id JOIN swganh.creature_groups g ON g.creature_group_id = l.creature_group SET la.value = '1824' WHERE g.creature_id = (SELECT id FROM swganh.non_persistent_npcs WHERE id BETWEEN 5001 AND 5999 AND stf_variable_id = 'bocatt' AND level = 19) AND la.attribute_id = (SELECT id FROM swganh.attributes WHERE name = 'creature_xp');
